"""Achats / ventes / forge / inventaire : 0 écu, stock épuisé, doublons, remises, limites."""
import sys; sys.path.insert(0,__import__('os').path.dirname(__import__('os').path.abspath(__file__)))
from qa_lib import *
q=QA('economie', viewport=(800,450)); q.load()
J=q.js
J('nouvelle partie',"T.newGame()","play")
J('achats avec 0 écu (toutes boutiques/articles)',"""(async()=>{const L=__lumen;const {SHOPS}=await import('/lumen/js/data/shops.js');L.st.player.ecus=0;const bad=[];let tries=0;
  for(const [sid,sh] of Object.entries(SHOPS)){L.G.screens.shop(sid,false);await T.tick(60);const btns=[...document.querySelectorAll('#screen [data-buy]')];for(const b of btns){tries++;const before=JSON.stringify([L.st.player.ecus,L.st.inv,L.st.unlocks]);b.click();await T.tick(30);if(JSON.stringify([L.st.player.ecus,L.st.inv,L.st.unlocks])!==before)bad.push(sid+':'+b.dataset.buy);}L.G.screens.close();}
  return JSON.stringify({tries,bad,ecus:L.st.player.ecus})})()""", lambda r: '"bad":[]' in r and '"ecus":0' in r)
J('achat au prix exact → 0 écu, jamais négatif',"""(async()=>{const L=__lumen;L.st.player.ecus=140;L.G.screens.shop('bran',false);await T.tick(100);const b=document.querySelector('#screen [data-buy=epee_courte]');b.click();await T.tick(100);const r1=L.st.player.ecus+' epee='+L.st.inv.epee_courte;
  L.G.screens.shop('bran',false);await T.tick(100);const again=document.querySelector('#screen [data-buy=epee_courte]');const dis=again?again.disabled:'absent';L.G.screens.close();return r1+' ré-achat bouton='+dis})()""","0 epee=1")
J('doublon arme: impossible de racheter',"""(async()=>{const L=__lumen;L.st.player.ecus=1000;const {SHOPS}=await import('/lumen/js/data/shops.js');const x={r:{id:'epee_courte',stock:1},price:140,out:false,owned:false};const e0=L.st.player.ecus;L.G.buy('bran',x);return 'epee='+L.st.inv.epee_courte+' ecus '+(e0-L.st.player.ecus)})()""", "epee=1 ecus 0")
J('stock consommable épuisé',"""(async()=>{const L=__lumen;L.st.player.ecus=9999;L.G.screens.shop('ysolde',false);await T.tick(100);let n=0;for(let i=0;i<10;i++){const b=document.querySelector('#screen [data-buy=potion]');if(!b||b.disabled)break;b.click();await T.tick(60);L.G.screens.shop('ysolde',false);await T.tick(60);n++;}const st=L.G.shopStock('ysolde');L.G.screens.close();return 'achetées='+n+' stock='+st.potion+' inv='+L.st.inv.potion})()""", lambda r: 'stock=0' in r)
J('repos restock',"""(async()=>{const L=__lumen;L.tpZone('auberge_in');await T.tick(400);const r=await T.talkTo('maelle',(n)=>0);await T.tick(500);return 'stock potion='+L.G.shopStock('ysolde').potion+' hp='+Math.round(L.st.player.hp)+' resp='+L.st.player.respawn.zone})()""", lambda r: 'stock potion=6' in r)
J('vente: dernier exemplaire',"""(async()=>{const L=__lumen;L.give('pierre',2);L.give('fibre',1);L.st.player.ecus=0;L.G.screens.shop('gaspard',true);await T.tick(100);const s=[...document.querySelectorAll('#screen [data-sell]')];const ids=s.map(b=>b.dataset.sell);
  document.querySelector('#screen [data-sell=fibre]').click();await T.tick(60);const e1=L.st.player.ecus;const fibre=L.st.inv.fibre;document.querySelector('#screen [data-sell=pierre]').click();await T.tick(60);document.querySelector('#screen [data-sell=pierre]').click();await T.tick(60);const left=L.st.inv.pierre;
  const txt=document.querySelector('#screen').innerText;L.G.screens.close();return JSON.stringify({ids,e1,fibre,left,ecus:L.st.player.ecus})})()""", '"fibre":null')
J('G.sell direct sur arme équipée (garde-fou)',"""(async()=>{const L=__lumen;const w=L.st.equip.weapon;L.G.sell(w);return 'arme='+w+' encore en inv='+!!L.st.inv[w]})()""", "encore en inv=true")
J('vente d\'un objet de quête via G.sell (garde-fou)',"""(async()=>{const L=__lumen;L.give('pendentif',1);L.G.sell('pendentif');return 'pendentif='+L.st.inv.pendentif})()""", "pendentif=1")
J('potion: pleine vie refusée / quick slot',"""(async()=>{const L=__lumen;L.give('potion',2);L.st.player.hp=L.G.stats().maxHp;const a=L.G.useItem('potion');L.st.player.hp=10;const b=L.G.useItem('potion');const n=L.st.inv.potion;L.st.inv.potion=0;delete L.st.inv.potion;L.st.equip.quick='potion';const c=L.G.useQuick();return JSON.stringify({a,b,n,c})})()""", '"a":false,"b":true')
# forge
J('forge: sans matériaux',"""(async()=>{const L=__lumen;L.give('epee_aube',1);L.st.player.ecus=0;L.G.screens.forge();await T.tick(100);const ups=[...document.querySelectorAll('#screen [data-up]')];const dis=ups.map(b=>b.disabled);const g0=L.st.gear.epee_aube;ups.forEach(b=>b.click());L.G.upgrade('epee_aube',1);await T.tick(60);const g1=L.st.gear.epee_aube;L.G.screens.close();return JSON.stringify({dis,g0,g1})})()""", '"g0":0,"g1":0')
J('forge: niveaux 1..3 + max',"""(async()=>{const L=__lumen;const out=[];L.st.player.ecus=5000;L.give('fibre',20);L.give('pierre',20);L.give('brume',20);L.give('larme_colosse',2);L.G.equip('epee_aube',true);const a0=L.G.stats().atk;
  for(let i=0;i<5;i++){L.G.upgrade('epee_aube',1);await T.tick(30);out.push(L.st.gear.epee_aube);}const a1=L.G.stats().atk;L.G.screens.forge();await T.tick(100);const txt=document.querySelector('#screen').innerText;L.G.screens.close();return JSON.stringify({out,a0,a1,max:txt.includes('Amélioration maximale'),ecus:L.st.player.ecus})})()""", '"out":[1,2,3,3,3]')
J('forge: remise -20 %',"""(async()=>{const L=__lumen;L.give('veste_cuir',1);L.st.flags.forge_remise=1;L.st.player.ecus=1000;L.give('fibre',10);L.G.upgrade('veste_cuir',0.8);return 'cuir+1 ecus='+L.st.player.ecus+' gear='+L.st.gear.veste_cuir})()""", "ecus=920")
J('fabrication: plastron une seule fois',"""(async()=>{const L=__lumen;L.st.player.ecus=2000;L.give('pierre',20);L.give('fibre',20);L.G.craft('plastron_ecailles',1);const n1=L.st.inv.plastron_ecailles;const e1=L.st.player.ecus;L.G.craft('plastron_ecailles',1);return 'n='+n1+' '+L.st.inv.plastron_ecailles+' dépense2='+(e1-L.st.player.ecus)})()""", "n=1 1 dépense2=0")
J('forge dans la Forêt (titre) via Silex',"""(async()=>{const L=__lumen;L.G.screens.forge();await T.tick(100);const t=document.querySelector('#screen h2').innerText;L.G.screens.close();return t})()""")
# inventaire : doublons & grosses piles
J('inventaire: doublons uniques / piles',"""(async()=>{const L=__lumen;const r=[];L.give('marteau',1);L.give('marteau',1);r.push('marteau='+L.st.inv.marteau);L.give('fragment_coeur',2);L.give('brume',500);r.push('brume='+L.st.inv.brume);L.give('objet_inexistant',3);r.push('inconnu='+L.st.inv.objet_inexistant);L.give('potion',0);L.give('potion',-5);r.push('potion='+L.st.inv.potion);
  L.G.screens.menu('inventaire');await T.tick(100);for(const c of ['arme','armure','accessoire','conso','materiau','quete']){document.querySelector('[data-cat='+c+']').click();await T.tick(40);const g=document.querySelectorAll('#m-body .cell').length;r.push(c+'='+g);}L.G.screens.close();return r.join(' ')})()""", lambda r: 'marteau=1' in r and 'inconnu=undefined' in r)
J('accessoires: 2 emplacements',"""(async()=>{const L=__lumen;['anneau_vie','anneau_prisme','amulette_lume'].forEach(i=>L.give(i,1));L.G.equip('anneau_vie',true);L.G.equip('anneau_prisme',true);L.G.equip('amulette_lume',true);return JSON.stringify({a1:L.st.equip.acc1,a2:L.st.equip.acc2,hp:L.G.stats().maxHp})})()""")
J('save/load après économie',"T.roundtrip('s1')","identique")
q.done()
